#include <iostream>
#include <array>
#include <string>
#include <cctype>

class HugeInt {
    friend std::ostream& operator<<(std::ostream& out, const HugeInt& num);
public:
    static constexpr int digits = 30;

    HugeInt(long value = 0) {
        integer.fill(0);
        for (int j = digits - 1; value != 0 && j >= 0; --j) {
            integer[j] = static_cast<short>(value % 10);
            value /= 10;
        }
    }

    HugeInt(const std::string& number) {
        integer.fill(0);
        int length = static_cast<int>(number.size());
        for (int j = digits - length, k = 0; j < digits; ++j, ++k) {
            if (std::isdigit(number[k])) {
                integer[j] = static_cast<short>(number[k] - '0');
            }
        }
    }

    HugeInt operator+(const HugeInt& op2) const {
        HugeInt temp;
        int carry = 0;
        for (int i = digits - 1; i >= 0; --i) {
            int sum = integer[i] + op2.integer[i] + carry;
            temp.integer[i] = static_cast<short>(sum % 10);
            carry = sum / 10;
        }
        return temp;
    }

    HugeInt operator+(int op2) const {
        return *this + HugeInt(op2);
    }

    HugeInt operator+(const std::string& op2) const {
        return *this + HugeInt(op2);
    }

private:
    std::array<short, digits> integer{};
};

std::ostream& operator<<(std::ostream& output, const HugeInt& num) {
    int i = 0;
    while (i < HugeInt::digits && num.integer[i] == 0) {
        ++i;
    }

    if (i == HugeInt::digits) {
        output << 0;
    } else {
        while (i < HugeInt::digits) {
            output << num.integer[i++];
        }
    }
    return output;
}

int main() {
    HugeInt n1(7654321);
    HugeInt n2(7891234);
    HugeInt n3("99999999999999999999999999999");
    HugeInt n4("1");
    HugeInt n5;

    std::cout << "n1 is " << n1 << "\n";
    std::cout << "n2 is " << n2 << "\n";
    std::cout << "n3 is " << n3 << "\n";
    std::cout << "n4 is " << n4 << "\n";
    std::cout << "n5 is " << n5 << "\n\n";

    n5 = n1 + n2;
    std::cout << n1 << " + " << n2 << " = " << n5 << "\n\n";

    std::cout << n3 << " + " << n4 << "\n= " << (n3 + n4) << "\n\n";

    n5 = n1 + 9;
    std::cout << n1 << " + 9 = " << n5 << "\n\n";

    n5 = n2 + "10000";
    std::cout << n2 << " + 10000 = " << n5 << "\n";

    return 0;
}
